import dlt

@dlt.table(
    name="consumer_order_mv",
    comment="Bronze view with current consumer_order records",
    table_properties={"quality": "bronze"}
)
def consumer_order_mv():
    df = dlt.read("consumer_order_cdc_stream")
    # Filter to current active records
    df_filtered = df.filter("__START_AT IS NOT NULL AND __END_AT IS NULL")
    # Drop SCD metadata columns and operation column as per metadata
    columns_to_drop = ["__START_AT", "__END_AT", "__OPERATION"]
    return df_filtered.drop(*columns_to_drop)

